// native_mic_register.cpp — registers every native of native_mic_decl.h with
// bronze (embed::registerNative) under __bro_native.mic. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_mic from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.mic.<Class>Proto for mic.js to chain.

#include "native_mic_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_mic(std::string* error) {
    const bool ok =
        fn("__bro_native.mic.start", p(&bro_mic_start), "void", {"bool", "i32", "bool", "i32", "bool", "bool", "bool", "bool", "bool", "bool", "dynamic", "bool", "f64", "bool", "f64", "bool", "f64", "bool", "f64"}, error) &&
        fn("__bro_native.mic.stop", p(&bro_mic_stop), "void", {}, error) &&
        fn("__bro_native.mic.isActive", p(&bro_mic_isActive), "bool", {}, error) &&
        fn("__bro_native.mic.engineRate", p(&bro_mic_engineRate), "i32", {}, error) &&
        fn("__bro_native.mic.stats", p(&bro_mic_stats), "bool", {}, error) &&
        fn("__bro_native.mic.stats_framesDelivered", p(&bro_mic_stats_framesDelivered), "f64", {}, error) &&
        fn("__bro_native.mic.stats_samplesDelivered", p(&bro_mic_stats_samplesDelivered), "f64", {}, error) &&
        fn("__bro_native.mic.stats_rollingPeak", p(&bro_mic_stats_rollingPeak), "f64", {}, error) &&
        fn("__bro_native.mic.stats_chunkCount", p(&bro_mic_stats_chunkCount), "f64", {}, error) &&
        fn("__bro_native.mic.stats_dropped", p(&bro_mic_stats_dropped), "f64", {}, error) &&
        fn("__bro_native.mic.stats_chunkFrames", p(&bro_mic_stats_chunkFrames), "i32", {}, error) &&
        fn("__bro_native.mic.levels", p(&bro_mic_levels), "f64[]", {"bool", "i32"}, error) &&
        fn("__bro_native.mic.feed", p(&bro_mic_feed), "void", {"f32[]", "bool", "i32"}, error);
    if (!ok) return false;
    return true;
}

}  // namespace bro::bronze_host
